package com.aoo.bcg.common.repair;import java.time.Instant;import java.util.*;
/** Persisted cursor and per-item failure history used for crash-safe repair resumption. */
public record DurableRepairCheckpoint(String operationId,String inputHash,String cursor,long succeeded,Map<String,Failure>failures,Instant updatedAt){public static final int MAX_RETRY_ATTEMPTS=5;public record Failure(String itemId,int attempts,String reason,boolean retryable,Instant failedAt){public Failure{if(itemId==null||itemId.isBlank()||attempts<1||reason==null||reason.isBlank()||failedAt==null)throw new IllegalArgumentException("invalid repair failure");}}public DurableRepairCheckpoint{if(operationId==null||operationId.isBlank()||inputHash==null||inputHash.isBlank()||cursor==null||succeeded<0||updatedAt==null)throw new IllegalArgumentException("invalid repair checkpoint");failures=Map.copyOf(failures==null?Map.of():failures);}public DurableRepairCheckpoint success(String nextCursor,Instant now){return new DurableRepairCheckpoint(operationId,inputHash,nextCursor,succeeded+1,failures,now);}public DurableRepairCheckpoint failure(String itemId,String reason,boolean retryable,Instant now){Map<String,Failure>next=new HashMap<>(failures);int attempts=Math.addExact(Optional.ofNullable(next.get(itemId)).map(Failure::attempts).orElse(0),1);next.put(itemId,new Failure(itemId,attempts,reason,retryable&&attempts<MAX_RETRY_ATTEMPTS,now));return new DurableRepairCheckpoint(operationId,inputHash,cursor,succeeded,next,now);}public List<Failure> retryQueue(){return failures.values().stream().filter(Failure::retryable).sorted(Comparator.comparing(Failure::failedAt).thenComparing(Failure::itemId)).toList();}public List<Failure> failureLedger(){return failures.values().stream().filter(failure->!failure.retryable()).sorted(Comparator.comparing(Failure::failedAt).thenComparing(Failure::itemId)).toList();}}
